// Copy button for code blocks. Shown on hover, on keyboard focus and always
// on touch screens. Icons: Tabler "copy" and "check" (outline, MIT).

const ICON_COPY = '<svg class="icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M7 7m0 2.667a2.667 2.667 0 0 1 2.667 -2.667h8.666a2.667 2.667 0 0 1 2.667 2.667v8.666a2.667 2.667 0 0 1 -2.667 2.667h-8.666a2.667 2.667 0 0 1 -2.667 -2.667z" /><path d="M4.012 16.737a2.005 2.005 0 0 1 -1.012 -1.737v-10c0 -1.1 .9 -2 2 -2h10c.75 0 1.158 .385 1.5 1" /></svg>'
const ICON_CHECK = '<svg class="icon" xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12l5 5l10 -10" /></svg>'
const RESET_AFTER = 2000

function copyText (text) {
  if (navigator.clipboard && window.isSecureContext) {
    return navigator.clipboard.writeText(text)
  }
  // Fallback for non-secure contexts (e.g. plain http)
  return new Promise(function (resolve, reject) {
    const area = document.createElement('textarea')
    area.value = text
    area.setAttribute('readonly', '')
    area.style.position = 'fixed'
    area.style.opacity = '0'
    document.body.appendChild(area)
    area.select()
    const ok = document.execCommand('copy')
    document.body.removeChild(area)
    ok ? resolve() : reject(new Error('copy failed'))
  })
}

function codeText (pre) {
  const code = pre.querySelector('code')
  return (code || pre).innerText.replace(/\n$/, '')
}

function addCopyButtons () {
  const live = document.createElement('span')
  live.className = 'is-sr-only'
  live.setAttribute('role', 'status')
  live.setAttribute('aria-live', 'polite')
  document.body.appendChild(live)

  function makeButton (getText) {
    const button = document.createElement('button')
    button.type = 'button'
    button.className = 'code-copy'
    button.setAttribute('aria-label', 'Copy code')
    button.innerHTML = ICON_COPY
    let timer = null

    button.addEventListener('click', function () {
      copyText(getText()).then(function () {
        button.classList.add('is-copied')
        button.innerHTML = ICON_CHECK
        button.setAttribute('aria-label', 'Copied')
        live.textContent = 'Code copied to clipboard'
        clearTimeout(timer)
        timer = setTimeout(function () {
          button.classList.remove('is-copied')
          button.innerHTML = ICON_COPY
          button.setAttribute('aria-label', 'Copy code')
          live.textContent = ''
        }, RESET_AFTER)
      }).catch(function () {
        live.textContent = 'Copy failed. Select the code and copy it manually.'
      })
    })
    return button
  }

  // Code blocks
  document.querySelectorAll('.content pre').forEach(function (pre) {
    // Skip line-number columns of tables generated by the highlighter
    if (pre.closest('.lntd') && !pre.closest('.lntd:last-child')) return
    const block = pre.closest('.highlight') || pre
    if (block.querySelector('.code-copy')) return
    block.classList.add('code-block')
    block.appendChild(makeButton(function () { return codeText(pre) }))
  })

  // Standalone inline code: a paragraph that contains only a code snippet,
  // such as an address or a command. The button sits to the right of it.
  document.querySelectorAll('.content p > code:only-child').forEach(function (code) {
    const p = code.parentElement
    if (p.textContent.trim() !== code.textContent.trim()) return
    if (p.querySelector('.code-copy')) return
    p.classList.add('code-line')
    const button = makeButton(function () { return code.textContent.trim() })
    button.classList.add('code-copy--inline')
    p.appendChild(button)
  })

  // Table cells and list items that contain only a code snippet, such as
  // cluster IDs. The button follows the snippet on the same line.
  document.querySelectorAll('.content td > code:only-child, .content li > code:only-child').forEach(function (code) {
    const cell = code.parentElement
    if (cell.textContent.trim() !== code.textContent.trim()) return
    if (cell.querySelector('.code-copy')) return
    cell.classList.add('code-cell')
    const button = makeButton(function () { return code.textContent.trim() })
    button.classList.add('code-copy--inline')
    cell.appendChild(button)
  })
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', addCopyButtons)
} else {
  addCopyButtons()
}
